            tip <- paste(c(adv$rec[[nm]], adv$caut[[nm]]), collapse = " ")
            tags$button(type = "button", `data-tip` = if (nzchar(tip)) tip,
                        class = paste("chip prod", if (items$key[i] %in% addons()) "on", if (rec) "rec", if (cau) "caut"),
