.force,.study{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:12px 16px;margin-bottom:10px}
.force h4,.study h4{margin-top:2px}
.takeaway{background:var(--cheese-soft);border-radius:12px;padding:12px 16px;margin:12px 0;font-size:.96rem;line-height:1.6}
.cites{display:inline-flex;flex-wrap:wrap;gap:4px;margin-left:6px;vertical-align:baseline}
.cite{font-size:.7rem;font-weight:600;color:var(--wine);background:var(--wine-soft);border-radius:6px;padding:1px 6px;text-decoration:none;white-space:nowrap}
.cite:hover{text-decoration:underline}
.fam-table{overflow-x:auto;margin:10px 0 12px}
.fam-table table{width:100%;border-collapse:collapse;font-size:.88rem;background:var(--surface);border-radius:12px;overflow:hidden}
.fam-table th{background:var(--surface2);text-align:left;padding:9px 10px;font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.fam-table td{padding:10px;border-top:1px solid var(--line);vertical-align:top;line-height:1.5}
.fam-table td:first-child{white-space:nowrap}

/* multi-pick flow */
.step-sub{margin:-2px 0 10px}
.prog{font-size:.8rem;font-weight:600;color:var(--muted);background:var(--surface2);border-radius:999px;padding:3px 10px}
.prog.ok{color:var(--good);background:var(--good-soft)}
.chip .count{background:var(--wine);color:#fff;border-radius:999px;font-size:.7rem;font-weight:700;padding:0 6px;min-width:18px;text-align:center}
.chip .tick{color:var(--wine);font-weight:700}
.picked{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-top:12px}
.picked .cl-h,.suggs .cl-h{font-size:.72rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:600;margin-right:4px}
.suggs{margin-top:14px;display:grid;gap:8px}
.sugg-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px}
.sugg{background:var(--cheese-soft);border-radius:12px;padding:12px 14px;display:grid;gap:6px;align-content:start}
.sugg-h{display:grid;gap:2px}
.sugg-h .nm{font-family:'Fraunces',Georgia,serif;font-size:1.05rem;display:flex;align-items:center;gap:6px}
.sugg .why{font-size:.88rem;color:var(--ink);margin:0}
.anchor{border-top:1px solid var(--line);padding-top:12px;margin-top:12px}
.anchor:first-of-type{border-top:0;margin-top:0;padding-top:0}
.anchor h4{font-family:'Fraunces',Georgia,serif;font-size:1.05rem;margin:0 0 8px}
.browse{margin-top:14px}
.browse summary{cursor:pointer;color:var(--wine);font-weight:600;font-size:.9rem}
.pairrow{background:var(--surface2);border-radius:12px;padding:12px 14px;margin-bottom:8px;display:grid;gap:4px}
.pairrow.miss{background:var(--warn-soft)}
.pr-head{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.pr-head .nm,.pr-head .wn{font-family:'Fraunces',Georgia,serif;font-size:1.02rem}
.pr-head .arrow{color:var(--muted)}
.pairrow .why{margin:0;font-size:.9rem}
.pairrow details summary{cursor:pointer;color:var(--wine);font-weight:600;font-size:.85rem}
.pairrow details .facts{margin-top:6px}
details.adv summary{cursor:pointer;font-family:'Fraunces',Georgia,serif;font-size:1.05rem}
details.adv .facts{margin-top:8px}

/* perfect bites */
.bites{margin:8px 0 6px}
.bites ol{margin:4px 0 0;padding-left:20px;display:grid;gap:8px}
.bite{display:flex;flex-wrap:wrap;align-items:center;gap:6px;font-size:.92rem}
.bite span:not(.plus){background:var(--surface);border:1px solid var(--line);border-radius:999px;padding:2px 10px}
.bite .b-cheese{background:var(--cheese-soft);border-color:var(--cheese)}
.bite .plus{color:var(--muted);font-weight:700}
.bite-why{font-size:.84rem;color:var(--muted);margin-top:2px}
.chip .newb{font-size:.62rem;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#fff;background:var(--good);border-radius:6px;padding:1px 6px}
